  "anecdota": "<p>تحكي أسطورة قديمة أن هوميروس، وقد صار شيخًا، التقى في جزيرة إيوس بفتيان عائدين من الصيد. سألهم عمّا اصطادوا، فأجابوه بلغز: «ما أمسكناه تركناه، وما لم نمسكه نحمله معنا». والشاعر الذي كان يعرف كل شيء عن الآلهة والأبطال لم يعرف كيف يحلّه. وكان الجواب هو القمل الذي نزعوه عن أنفسهم وهم جالسون على الشاطئ. وقد أشار هيراقليطس إلى هذه الحكاية ليسخر ممن يثقون بحكمة الشعراء: حتى أعظم اليونانيين انخدع بما كان أمام عينيه.</p>",
